import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import '../services/user_preferences_service.dart';
import '../services/notification_service.dart';

class PreferencesScreen extends StatefulWidget{const PreferencesScreen({super.key});@override State<PreferencesScreen> createState()=>_PreferencesScreenState();}
class _PreferencesScreenState extends State<PreferencesScreen>{
  static const options=[('PK','Pakistan','PKR','Rs'),('IE','Ireland','EUR','€'),('GB','United Kingdom','GBP','£'),('US','United States','USD','\$'),('AE','United Arab Emirates','AED','AED'),('SA','Saudi Arabia','SAR','SAR'),('IN','India','INR','₹'),('CA','Canada','CAD','C\$'),('AU','Australia','AUD','A\$')];
  late String country,currency,symbol; late bool notifications; bool busy=false;
  @override void initState(){super.initState();final p=UserPreferencesService.instance;country=p.countryCode;currency=p.currencyCode;symbol=p.currencySymbol;notifications=p.notificationsEnabled;}
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Preferences')),body:ListView(padding:const EdgeInsets.all(20),children:[
    Text('Personalise PennyPal',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:6),const Text('Choose how money and regional information should appear in your account.'),const SizedBox(height:22),
    Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(children:[DropdownButtonFormField<String>(initialValue:country,decoration:const InputDecoration(labelText:'Country / region',prefixIcon:Icon(Icons.public_rounded)),items:options.map((o)=>DropdownMenuItem(value:o.$1,child:Text(o.$2))).toList(),onChanged:(v){if(v==null)return;final o=options.firstWhere((e)=>e.$1==v);setState((){country=o.$1;currency=o.$3;symbol=o.$4;});}),const SizedBox(height:14),DropdownButtonFormField<String>(initialValue:currency,decoration:const InputDecoration(labelText:'Primary currency',prefixIcon:Icon(Icons.currency_exchange_rounded)),items:options.map((o)=>o.$3).toSet().map((c){final o=options.firstWhere((e)=>e.$3==c);return DropdownMenuItem(value:c,child:Text('$c (${o.$4})'));}).toList(),onChanged:(v){if(v==null)return;final o=options.firstWhere((e)=>e.$3==v);setState((){currency=o.$3;symbol=o.$4;});}),const SizedBox(height:10),SwitchListTile(contentPadding:EdgeInsets.zero,value:notifications,onChanged:(v)=>setState(()=>notifications=v),title:const Text('Notifications'),subtitle:const Text('Budget, goal and important PennyPal reminders'))]))),const SizedBox(height:18),
    FilledButton.icon(onPressed:busy?null:()async{setState(()=>busy=true);await UserPreferencesService.instance.save(FirebaseAuth.instance.currentUser!.uid,country:country,currency:currency,symbol:symbol,notifications:notifications);if(notifications)await NotificationService.instance.enablePush();if(!context.mounted)return;setState(()=>busy=false);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Preferences saved')));},icon:const Icon(Icons.check_rounded),label:Text(busy?'Saving…':'Save preferences')),
    const SizedBox(height:14),const Text('PennyPal uses one primary currency per account. Existing amounts are not automatically converted when you change currency.',style:TextStyle(fontSize:12,color:Color(0xFF71807A),height:1.4))
  ]));}
